-- Website CRK Group: data outlet (34 kios) + dua penyesuaian tabel outlet.
-- Jalankan sekali di Supabase SQL Editor. Aman dijalankan ulang.

-- 1) Kolom tautan Google Maps (dipakai tombol "Petunjuk arah").
alter table public.outlets add column if not exists gmaps_url text;

-- 2) Status baru 'segera' untuk kios yang belum buka.
alter table public.outlets drop constraint if exists outlets_status_check;
alter table public.outlets add constraint outlets_status_check check (status in ('buka', 'segera', 'tutup'));
drop policy if exists "publik baca outlet" on public.outlets;
create policy "publik baca outlet" on public.outlets for select using (status in ('buka', 'segera') or public.is_staff());

-- 3) Data kios dari sheet "All Kios" (13 Nov 2026).
--    Koordinat 9 kios 'segera' diambil dari tautan Google Maps (titik persis).
--    Koordinat 25 kios 'buka' adalah PERKIRAAN dari alamat; ganti dengan titik persis sebelum launch.
on conflict (store_code) do update set
  name = excluded.name, city = excluded.city, address = excluded.address, landmark = excluded.landmark,
  hours = excluded.hours, lat = excluded.lat, lng = excluded.lng, gmaps_url = excluded.gmaps_url, status = excluded.status;

-- Hapus outlet contoh bila pernah diisi.
delete from public.outlets where store_code like 'CONTOH-%';
